    #: ③ HTTP 侧:实际 wire 交换(per-attempt 一条)。
    exchanges: List["_dto.HttpExchange"] = Field(alias="exchanges")
    #: ① 输入侧:调用参数(prompt + options)。
    input: "_dto.InputRecord" = Field(alias="input")
